from datetime import date


def parse_date(text: str) -> date:
    if "-" in text:
        return date.fromisoformat(text)
    if "/" in text:
        day, month, year = text.split("/")
        return date(int(year), int(month), int(day))
    raise ValueError(f"Unrecognised date: {text!r}")
